const $=s=>document.querySelector(s);
const siteRemote=location.pathname.startsWith('/app/hyblog/');
let connectionPoll;
async function apiFetch(route,options){const response=await fetch(siteRemote?'./api.py?route='+encodeURIComponent(route):route,options);if(!response.headers.get('content-type')?.includes('application/json')){const message=response.status===401?'이 기기를 먼저 연결해주세요.':response.status===403?'연결 권한을 확인해주세요.':response.status===413?'사진 용량을 줄여 다시 시도해주세요.':'사이트 연결을 확인하고 있어요. 잠시 후 다시 시도해주세요.';return new Response(JSON.stringify({error:message}),{status:response.ok?502:response.status,headers:{'Content-Type':'application/json'}});}return response;}
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={plus:'M12 5v14M5 12h14',edit:'m16 3 5 5-12 12-6 1 1-6L16 3ZM14 5l5 5',book:'M4 3h14a2 2 0 0 1 2 2v16H5a3 3 0 0 1 0-6h15M5 3v12',photo:'M4 3h16v18H4zM4 16l5-5 4 4 3-3 4 4M15 7h.01',pin:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0ZM12 7a3 3 0 1 0 0 6 3 3 0 0 0 0-6',spark:'m12 3 2.6 6.4L21 12l-6.4 2.6L12 21l-2.6-6.4L3 12l6.4-2.6L12 3ZM20 3v4M18 5h4',arrow:'M5 12h14m-5-5 5 5-5 5',check:'m5 12 4 4L19 6',chevron:'m9 5 7 7-7 7',close:'m6 6 12 12M6 18 18 6',up:'m5 15 7-7 7 7',down:'m5 9 7 7 7-7',leaf:'M20 3C7 1 1 11 6 17s16 4 14-14ZM5 20 16 8',info:'M12 17v-5m0-5v.01M22 12A10 10 0 1 1 2 12a10 10 0 0 1 20 0',copy:'M8 8h13v13H8zM16 8V3H3v13h5',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12ZM12 9a3 3 0 1 0 0 6 3 3 0 0 0 0-6',clock:'M12 8v5l3 2M22 12A10 10 0 1 1 2 12a10 10 0 0 1 20 0',fork:'M6 3v7m4-7v7M4 3v7h8M8 10v11M19 3c-4 2-4 9 0 9V3Zm0 9v9',guide:'M4 3h7v18H4zM13 3h7v18h-7zM7 7h1M7 11h1M16 7h1M16 11h1',text:'M4 5h16M12 5v16M8 21h8',back:'M20 12H4m6-6-6 6 6 6',trash:'M3 6h18M9 6V3h6v3M6 6l1 15h10l1-15M10 10v7M14 10v7'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.photo}"/></svg>`;
const fresh=()=>({id:crypto.randomUUID(),place:'',area:'',link:'',visitDate:'',visitTime:'',alignment:'center',naverAutoSave:true,receipts:[],useReviews:true,reviewLinks:'',menus:'',notes:'',facts:'',sponsorship:'unknown',style:'natural',stickers:true,photos:[],draft:null,modifiedAt:Date.now()});
let state=fresh(),library=[],view='input',preview=false,connection={ready:false,message:'Codex 연결 확인 중'},error='',jobId=null,jobStage='',jobStarted=0,photoBusy=false,saveTimer,db,toastTimer,pollTimer;
let jobAttention=null;
let storageReady=false,saving=Promise.resolve(),submitting=false;
function forkInput(){
  if(!state.draft)return;
  saveNow();
  state={...structuredClone(state),id:crypto.randomUUID(),draft:null,modifiedAt:Date.now()};
  document.querySelectorAll('[data-action="editor"],[data-action="export"]').forEach(el=>el.disabled=true);
  const generate=$('#generate');if(generate)generate.innerHTML=icon('spark')+'초안 만들기'+icon('arrow');
  toast('이전 수정본을 보관하고 새 입력으로 이어갑니다.');
}
async function openDB(){return await new Promise((resolve,reject)=>{const req=indexedDB.open('meal-note-v1',1);req.onupgradeneeded=()=>req.result.createObjectStore('drafts',{keyPath:'id'});req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});}
function storeOp(mode,fn){return new Promise((resolve,reject)=>{const tx=db.transaction('drafts',mode);const req=fn(tx.objectStore('drafts'));tx.oncomplete=()=>resolve(req.result);tx.onerror=()=>reject(tx.error);});}
function hasContent(){return !!(state.place||state.area||state.link||state.visitDate||state.visitTime||state.menus||state.notes||state.facts||state.photos.length||state.receipts?.length||state.draft);}
let saveStatus='empty',lastSavedAt=0,networkRetries=0,jobRequestActive=false,progressClock;
function savedMessage(){return saveStatus==='error'?'저장 실패 · 작업 파일로 보관해주세요':saveStatus==='saving'?'임시저장 중…':lastSavedAt?'이 기기에 '+new Date(lastSavedAt).toLocaleTimeString('ko-KR',{hour:'2-digit',minute:'2-digit'})+' 임시저장됨':'입력하면 이 기기에 자동 저장돼요';}
function updateSaveLabels(){document.querySelectorAll('[data-save-status],#saved-label').forEach(el=>{el.textContent=savedMessage();el.dataset.status=saveStatus;});}
function focusProgress(){window.scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});$('#generation-progress')?.focus({preventScroll:true});}
function startClock(){clearInterval(progressClock);progressClock=setInterval(()=>{const t=$('#job-time');if(t)t.textContent=elapsed();if(!jobId&&!submitting)clearInterval(progressClock);},1000);}
function saveBar(){return `<section class="save-bar" aria-label="작업 임시저장"><div><strong>사진과 입력, 이어서 쓰기</strong><span data-save-status role="status">${esc(savedMessage())}</span></div><div><button class="button" data-action="save-input">${icon('check')}임시저장</button><button class="muted-link" data-action="download-json">작업 파일 받기</button></div></section>`;}
function recoveryEvents(){window.addEventListener('online',()=>{if(jobId)pollJob();else if(state.pendingRequest)submitGeneration();});window.addEventListener('pageshow',()=>{if(jobId)pollJob();});document.addEventListener('visibilitychange',()=>{if(!document.hidden){if(jobId)pollJob();else if(state.pendingRequest)submitGeneration();}});}
async function saveNow(){
  clearTimeout(saveTimer);if(!hasContent())return true;
  if(!storageReady){saveStatus='error';updateSaveLabels();return false;}
  state.modifiedAt=Date.now();const snapshot=structuredClone(state);saveStatus='saving';updateSaveLabels();
  const operation=saving.catch(()=>{}).then(async()=>{
    await storeOp('readwrite',s=>s.put(snapshot));
    try{localStorage.setItem('meal-note-current',snapshot.id);}catch{}
    library=await storeOp('readonly',s=>s.getAll());library.sort((a,b)=>b.modifiedAt-a.modifiedAt);
    lastSavedAt=snapshot.modifiedAt;saveStatus='saved';updateSaveLabels();
  });saving=operation;
  try{await operation;return true;}catch{saveStatus='error';updateSaveLabels();toast('이 기기의 저장 공간이 부족해요. 작업 파일 받기로 사진과 입력을 보관해주세요.');return false;}
}
function scheduleSave(){saveStatus='saving';updateSaveLabels();clearTimeout(saveTimer);saveTimer=setTimeout(saveNow,350);}
function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),3500);}
function elapsed(){return Math.floor((Date.now()-jobStarted)/1000);}
function header(){return `<header class="topbar"><a href="./" class="brand" aria-label="망나 모먼트 홈"><img src="./mark.svg" alt=""><strong>망나 모먼트</strong><small>MANGNA moment</small></a><div class="topright"><span class="saved-top" id="saved-label">${esc(savedMessage())}</span><button class="badge ${connection.ready?'':'off'}" data-action="status" title="Codex 연결 다시 확인"><span class="dot"></span>${connection.ready?'Codex 구독 연결':'연결 확인'}</button><button class="avatar" data-action="help" aria-label="사용 방법">?</button></div></header>`;}
function sidebar(){return `<aside class="sidebar"><div class="side-label">MY WORKSPACE</div><button class="navitem ${view!=='library'?'active':''}" data-action="workspace">${icon('edit')}<span>글 작업실</span></button><button class="navitem ${view==='library'?'active':''}" data-action="library">${icon('book')}<span>내 보관함</span><span class="count">${library.length}</span></button><button class="navitem" data-action="new">${icon('plus')}<span>새 글 시작하기</span></button><div class="recent-title">최근 기록</div><div class="recent-list">${library.slice(0,5).map(d=>`<button class="recent" data-action="load" data-id="${d.id}" title="${esc(d.place)}">${esc(d.place||'이름 없는 기록')}</button>`).join('')||'<div class="recent">첫 번째 이야기를 남겨보세요</div>'}</div></aside>`;}
function mobileNav(){return `<nav class="mobile-nav"><button data-action="workspace" class="${view!=='library'?'active':''}">글 작업실</button><button data-action="library" class="${view==='library'?'active':''}">내 보관함 ${library.length}</button><button data-action="new">+ 새 글</button></nav>`;}
function steps(){return `<div class="workflow"><button class="step ${view==='input'?'active':''}" data-action="input"><strong>1</strong>지점과 사진</button><button class="step ${view==='editor'?'active':''}" data-action="editor" ${!state.draft?'disabled':''}><strong>2</strong>초안 다듬기</button><button class="step" data-action="export" ${!state.draft?'disabled':''}><strong>3</strong>내보내기</button></div>`;}
function progress(){return jobId||submitting?`<section class="progress-box" id="generation-progress" tabindex="-1" aria-label="초안 생성 진행 상황">${attentionCard(jobAttention)}<div class="progress-title" role="status"><span class="spinner"></span><span id="job-stage">${esc(jobStage||'사진과 입력을 안전하게 보관하고 있어요')}</span></div><div class="progress-track" aria-hidden="true"><i></i></div><p>진행 상황은 자동으로 갱신돼요. 확인이 필요한 단계는 위에 안내합니다.<br><span id="job-time">${elapsed()}</span>초 경과 · 연결이 끊겨도 이 기기에서 이어서 확인할 수 있어요.</p><div class="progress-actions"><button class="button" data-action="save-input">입력 임시저장</button><button class="muted-link" data-action="retry-job">진행 다시 확인</button>${jobId?'<button class="muted-link" data-action="cancel">생성 취소</button>':''}</div></section>`:'';}
function field(name,label,placeholder='',type='text'){return `<div class="field"><label for="${name}">${label}</label><input id="${name}" data-field="${name}" type="${type}" value="${esc(state[name])}" placeholder="${esc(placeholder)}" ${name==='place'?'maxlength="120"':''}></div>`;}
function inputView(){return `<div class="workspace-heading"><h1>새 글 쓰기</h1></div>${progress()}${steps()}${error?`<div class="error-box" role="alert">${esc(error)}</div>`:''}<div class="work-grid"><div><section class="card"><div class="card-heading"><h2><span class="number">01</span>어디에 다녀오셨나요?</h2><span class="required">필수</span></div><div class="place-row">${field('place','식당 이름 · 지점','예: 오봉집 광교점')}${mapButton()}</div><div class="field-row">${field('area','동네 <span class="optional">선택</span>','예: 수원 광교')}</div>${locationFields()}${visitPicker()}<details class="notes-card"><summary>확인한 매장 정보 추가</summary>${field('link','지도 링크','네이버 지도 또는 매장 공식 페이지 주소')}<div class="field"><label for="facts">직접 확인한 정보</label><textarea id="facts" data-field="facts" placeholder="주소, 영업시간, 주차 조건 등 확인한 내용만 적어주세요.">${esc(state.facts)}</textarea><p class="hint">매장 링크와 직접 확인한 정보를 남겨주세요. 운영 정보는 직접 확인한 내용만 반영해요.</p></div></details></section><section class="card"><div class="card-heading"><h2><span class="number">02</span>사진과 동영상을 모아주세요</h2><span class="required" id="photo-count">${state.photos.length} / 24장</span></div><button class="upload-zone" id="dropzone" data-action="upload" ${photoBusy||jobId?'disabled':''}><div class="upload-art">${icon('photo')}</div><strong>${photoBusy?'사진·움짤을 준비하고 있어요…':'사진·동영상을 끌어 놓거나 선택해주세요'}</strong><span>동영상은 처음 4초를 자동으로 움짤로 만들어요</span><span class="choose">+ 사진·동영상 선택</span></button><input type="file" id="photo-picker" accept="image/*,video/mp4,video/quicktime,video/webm,.mov" multiple hidden><div class="upload-foot"><span>사진·GIF·MP4·MOV / 총 24개, 영상 4개·각 50MB</span><span>사진 순서는 나중에 바꿔도 괜찮아요</span></div>${mediaProgressView()}${state.photos.length?`<div class="photo-grid">${state.photos.map((p,i)=>`<div class="photo">${mediaView(p)}<span class="photo-index">${i+1}</span><div class="photo-actions"><button class="icon-btn move-photo" data-action="photo-up" data-id="${p.id}" aria-label="${i+1}번 사진 앞으로" ${i===0||jobId?'disabled':''}>${icon('up')}</button><button class="icon-btn" data-action="photo-remove" data-id="${p.id}" aria-label="${i+1}번 사진 삭제" ${jobId?'disabled':''}>${icon('close')}</button></div><input data-photo-note="${p.id}" value="${esc(p.note)}" placeholder="메뉴 이름·메모 (선택)" aria-label="${i+1}번 사진 설명" maxlength="500">${mediaTools(p)}</div>`).join('')}</div>`:''}<p class="hint">영상 원본은 이 브라우저에 보관해요. AI에는 대표 장면과 설명만 보내며, 소리·영상 전체는 분석하지 않아요.</p></section>${receiptPanel()}${researchOptions()}${naverOptions()}<section class="card"><div class="card-heading"><h2><span class="number">03</span>기억나는 이야기 <span class="optional">선택</span></h2></div><div class="field"><label for="notes">첫 입의 맛, 잘 어울린 조합, 양은 어땠나요?</label><textarea id="notes" data-field="notes" maxlength="4000" placeholder="예: 양념이 살짝 매콤했고, 미나리랑 먹으니 느끼하지 않았어. 처음엔 양이 적을까 했는데 볶음밥까지 먹으니 배불렀어.">${esc(state.notes)}</textarea><p class="hint">맛있었던 조합이나 마지막 한 입의 느낌을 한두 줄만 적어주세요. 내 말투로 풀어드릴게요.</p></div>${field('menus','주문한 메뉴 · 가격 <span class="optional">선택</span>','예: 낙지볶음 2인, 보쌈 소')}${paymentFields()}</section></div></div>${inputActions()}`;}
function articlePart(key,cls=''){return preview?`<div class="read-text ${cls}">${esc(state.draft[key])}</div>`:`<textarea class="auto-grow ${cls}" data-draft-field="${key}" aria-label="${{title:'글 제목',intro:'첫 문단',closing:'마무리 문단'}[key]}">${esc(state.draft[key])}</textarea>`;}
function editorView(){const d=state.draft;if(!d)return inputView();return `<div class="workspace-heading"><h1>초안 다듬기</h1><p>고친 내용은 자동으로 저장돼요.</p></div>${progress()}${steps()}${saveBar()}${naverResult()}<div class="editor-toolbar"><div><button class="button" data-action="input">${icon('back')}입력 보기</button><button class="button ${preview?'soft':''}" data-action="preview">${icon(preview?'edit':'eye')}${preview?'편집하기':'미리보기'}</button></div><div>${alignmentControl()}${paymentToggle()}<label class="check-line sticker-toggle"><input type="checkbox" id="draft-stickers" ${d.stickers===true?'checked':''}>네이버 스티커</label><button class="button naver-button" data-action="naver">네이버 임시저장</button><small id="char-count">${plainText().length.toLocaleString()}자</small><button class="button" data-action="copy">${icon('copy')}본문 복사</button><button class="button primary" data-action="export">${icon('download')}내보내기</button></div></div><div class="editor-grid"><aside class="editor-info"><div><h3>함께 담은 사진 <span class="optional">${state.photos.length}</span></h3><div class="photo-strip">${state.photos.map((p,i)=>`<figure><img src="${p.data}" alt="${esc(p.name)}"><figcaption>${i+1}. ${esc(p.note||p.name)}</figcaption></figure>`).join('')}</div><p class="hint">사진 위치는 문단의 화살표로 바꿀 수 있어요.</p></div>${d.checks.length?`<div class="checks"><h4>${icon('info')}발행 전에 확인해주세요</h4><ul>${d.checks.map(c=>`<li>${esc(c)}</li>`).join('')}</ul></div>`:''}${researchPanel()}${state.draft?.receipt&&state.receipts?.length?receiptPanel():''}</aside><article class="article ${state.alignment!=='left'?'centered':''}"><div class="article-label">MANGNA MOMENT</div>${articlePart('title',preview?'read-title':'title-input')}${!preview?`<div class="title-options">${d.titles.map((t,i)=>`<button data-action="title" data-index="${i}" title="${esc(t)}"><span>제안 ${i+1}</span>${esc(t)}</button>`).join('')}</div>`:''}<div class="article-meta">${esc(state.place)}${state.visitDate?' · '+esc(state.visitDate):''}${state.visitTime?' '+esc(state.visitTime):''} · ${state.sponsorship==='self'?'직접 결제':state.sponsorship==='provided'?'식사 제공':'방문 기록'}</div>${disclosureMarkup()}${articlePart('intro')}${d.sections.map((s,i)=>`<section class="article-section"><div class="section-heading">${preview?`<h2 class="read-heading">${esc(s.heading)}</h2>`:`<input data-section="${s.id}" data-prop="heading" value="${esc(s.heading)}" aria-label="${i+1}번 문단 소제목"><div class="section-actions"><button class="icon-btn" data-action="section-up" data-id="${s.id}" aria-label="${i+1}번 문단 위로" ${i===0?'disabled':''}>${icon('up')}</button><button class="icon-btn" data-action="section-down" data-id="${s.id}" aria-label="${i+1}번 문단 아래로" ${i===d.sections.length-1?'disabled':''}>${icon('down')}</button></div>`}</div>${preview?sectionPreview(s):`<div class="article-images edit-images">${s.photoIds.map(id=>{const p=state.photos.find(p=>p.id===id);return p?mediaView(p,'article-media'):'';}).join('')}</div><textarea class="auto-grow" data-section="${s.id}" data-prop="body" aria-label="${i+1}번 문단 본문">${esc(s.body)}</textarea>`}${stickerMarkup(i)}</section>`).join('')}${!preview?`<button class="muted-link" data-action="add-section">+ 내 이야기 문단 추가</button>`:''}${articlePart('closing')}${preview?`<div class="read-text tags-input">${d.tags.map(t=>'#'+esc(t.replace(/^#/,''))).join(' ')}</div>`:`<input class="tags-input" data-draft-field="tags" value="${esc(d.tags.map(t=>'#'+t.replace(/^#/, '')).join(' '))}" aria-label="해시태그">`}${locationPreview(d.location)}</article></div><div class="editor-bottom"><button class="muted-link" data-action="generate" ${jobId?'disabled':''}>다른 초안도 만들기 · 현재 수정본은 보관돼요</button></div>`;}
function libraryView(){return `<div class="intro-row"><div><p class="eyebrow">SAVED DRAFTS</p><h1>내 보관함</h1><p class="lead">이 브라우저에 저장된 사진과 글입니다. 중요한 기록은 파일로도 보관해주세요.</p></div><button class="button primary" data-action="new">${icon('plus')}새 글</button></div>${library.length?`<div class="library-grid">${library.map(d=>`<button class="draft-card" data-action="load" data-id="${d.id}"><div class="draft-cover">${d.photos[0]?`<img src="${d.photos[0].data}" alt="">`:icon('book')}</div><div class="draft-info"><small>${d.pendingJob||d.pendingRequest?'생성 중 · 이어 확인하기':d.draft?'작성한 초안':'입력 임시저장'}</small><h3>${esc(d.draft?.title||d.place||'새로운 기록')}</h3><p>${new Date(d.modifiedAt).toLocaleString('ko-KR',{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'})} · 사진 ${d.photos.length}장</p></div></button>`).join('')}</div>`:`<div class="empty-library">${icon('book')}<h3>첫 번째 맛있는 기록을 기다려요</h3><p>사진을 넣고 글을 시작하면 여기에 자동으로 보관됩니다.</p><button class="button" data-action="new">첫 글 시작하기</button></div>`}<div class="toolbar-mini"><button class="muted-link" data-action="import">보관한 작업 파일 불러오기</button><input id="import-picker" type="file" accept="application/json,.json" hidden></div>`;}
function pairPanel(){return siteRemote&&connection.authRequired?`<section class="pair-panel"><div><h2>${connection.pairCode?'이 번호로 기기를 연결해주세요':'나만의 맛집 작업실에 연결해요'}</h2><p>${connection.pairCode?'초안 생성 PC의 연결 관리 화면에서 같은 번호를 승인하면 자동으로 연결됩니다.':'처음 쓰는 브라우저는 한 번만 연결하면 돼요. 승인된 기기에서 사진으로 초안을 만들 수 있어요.'}</p>${connection.pairCode?`<strong class="pair-code">${esc(connection.pairCode)}</strong><small>15분 동안 유효 · 승인 후 자동으로 열립니다</small>`:`<button class="button primary" data-action="pair">이 기기 연결하기</button>`}</div></section>`:'';}
function render(){const scroll=window.scrollY,focused=document.activeElement,focusId=focused?.id,selection=focused&&'selectionStart' in focused?[focused.selectionStart,focused.selectionEnd]:null;$('#app').innerHTML=header()+`<div class="shell">${sidebar()}<main class="content">${mobileNav()}${pairPanel()}${view==='library'?libraryView():view==='editor'?editorView():inputView()}<footer class="footer"><span>망나 모먼트 · v0.5.1</span><span>${siteRemote?'망나 모먼트':'이 PC에서 이용'} · 사진과 초안은 이 브라우저에 저장</span></footer></main></div>`;document.querySelectorAll('.auto-grow').forEach(grow);if(jobId||submitting||photoBusy)document.querySelectorAll('#naver-auto,#location-confirmed,#input-stickers,#draft-stickers,[data-field],[data-photo-note],[data-action="style"],[data-action="generate"],[data-action="upload"],[data-action="receipt-upload"]').forEach(el=>el.disabled=true);bindDrop();if(focusId){const next=document.getElementById(focusId);if(next&&!next.disabled){next.focus({preventScroll:true});if(selection)try{next.setSelectionRange(...selection);}catch{}}}window.scrollTo(0,scroll);}
function grow(el){el.style.height='auto';el.style.height=el.scrollHeight+2+'px';}
async function checkStatus(){clearTimeout(connectionPoll);const old=JSON.stringify(connection);try{const response=await apiFetch('/api/status');if(!response.ok)throw Error();connection=await response.json();}catch{connection={ready:false,message:siteRemote?'사이트 연결을 확인하고 있어요. 잠시 후 다시 시도해주세요.':'로컬 서버와 연결되지 않았어요. 한편 시작 파일을 다시 실행해주세요.'};}if(old!==JSON.stringify(connection))render();if(siteRemote)connectionPoll=setTimeout(checkStatus,connection.authRequired&&connection.pairCode?3000:30000);}
async function pairDevice(){const response=await apiFetch('/api/pair',{method:'POST',headers:{'Content-Type':'application/json','X-Meal-Note':'1'},body:JSON.stringify({name:/iPhone|iPad/.test(navigator.userAgent)?'아이폰 · 아이패드':/Android/.test(navigator.userAgent)?'안드로이드':'PC 브라우저'})});const result=await response.json();if(!response.ok)throw Error(result.error);await checkStatus();window.scrollTo({top:0,behavior:'smooth'});}
function bindDrop(){const zone=$('#dropzone');if(!zone)return;for(const evt of ['dragenter','dragover'])zone.addEventListener(evt,e=>{e.preventDefault();zone.classList.add('dragover');});for(const evt of ['dragleave','drop'])zone.addEventListener(evt,e=>{e.preventDefault();zone.classList.remove('dragover');});zone.addEventListener('drop',e=>addPhotos(e.dataTransfer.files));}
async function compressedImage(file){if(file.size>30*1024*1024)throw new Error(`${file.name}: 30MB 이하 사진을 넣어주세요.`);const url=URL.createObjectURL(file);try{const img=await new Promise((resolve,reject)=>{const image=new Image();image.onload=()=>resolve(image);image.onerror=()=>reject(new Error(`${file.name}: 이 브라우저에서 읽을 수 없어요. HEIC 사진은 JPG로 변환해서 넣어주세요.`));image.src=url;});if(img.naturalWidth*img.naturalHeight>100000000)throw new Error(`${file.name}: 사진 해상도가 너무 높아요.`);const scale=Math.min(1,1600/Math.max(img.naturalWidth,img.naturalHeight));const canvas=document.createElement('canvas');canvas.width=Math.round(img.naturalWidth*scale);canvas.height=Math.round(img.naturalHeight*scale);const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);return canvas.toDataURL('image/jpeg',.82);}finally{URL.revokeObjectURL(url);}}
async function addPhotos(files){
 if(jobId||submitting||photoBusy)return;
 const list=Array.from(files);if(!list.length)return;
 if(state.photos.length+list.length>24)return toast('사진은 한 글에 최대 24장까지 넣을 수 있어요.');
 forkInput();photoBusy=true;error='';render();const failures=[];
 for(const file of list){try{
  updateMediaProgress(file.name+' 준비 중');
  const media=await prepareMedia(file),p={id:crypto.randomUUID(),name:file.name,note:'',...media};state.photos.push(p);
  // Persist the original before encoding, so an interrupted phone session can resume.
  if(!await saveNow())throw Error('기기 저장 공간이 부족해요. 작업 파일을 내려받아 보관해주세요.');
  if(p.kind==='video')await encodeVideoGif(p);
  await saveNow();
 }catch(e){failures.push(e.message);}}
 photoBusy=false;mediaProgress='';error=failures.join(' ');await saveNow();render();
 if(!failures.length)toast('사진과 움짤을 담았어요. 움직이는 미리보기를 확인해주세요.');
}

function generationInput(){return {place:state.place,area:state.area,link:state.link,visitDate:state.visitDate,menus:state.menus,notes:state.notes,facts:state.facts,style:'natural',location:confirmedLocation(),stickers:state.stickers!==false,sponsorship:state.sponsorship,visitTime:state.visitTime||'',useReviews:state.useReviews!==false,reviewLinks:state.reviewLinks||'',naverAutoSave:state.naverAutoSave!==false,receipts:(state.receipts||[]).map(({id,name,data})=>({id,name,data})),photos:state.photos.map(({id,name,note,data,kind,gifData})=>({id,name,kind,gifData:safeGif(gifData)?gifData:undefined,note:(kind==='video'?'[영상의 대표 장면] ':'')+note,data}))};}
async function startGeneration(){
  if(jobId||submitting||photoBusy)return;
  if(!state.place.trim()){error='식당 이름과 지점을 먼저 입력해주세요.';view='input';render();$('#place')?.focus();return;}
  if(!state.photos.length){error='그날 찍은 사진을 한 장 이상 넣어주세요.';view='input';render();window.scrollTo({top:0,behavior:'smooth'});return;}
  if(!await ensureGifs())return;
  error='';submitting=true;view='input';jobStarted=Date.now();jobAttention=null;jobStage='사진과 입력을 임시저장하고 있어요';render();focusProgress();startClock();
  if(!await saveNow()){submitting=false;error='임시저장 공간을 확인해주세요. 먼저 작업 파일을 내려받으면 입력과 사진을 따로 보관할 수 있어요.';render();return;}
  if(state.draft)state={...structuredClone(state),id:crypto.randomUUID(),draft:null,modifiedAt:Date.now()};
  state.pendingRequest={id:crypto.randomUUID(),startedAt:jobStarted};
  if(!await saveNow()){delete state.pendingRequest;submitting=false;render();return;}
  await submitGeneration();
}
async function submitGeneration(){
  if(jobRequestActive||!state.pendingRequest)return;
  if(Date.now()-state.pendingRequest.startedAt>23*60*60*1000){await finishFailure('접수 확인 기한이 지났어요. 임시저장한 사진과 입력으로 다시 만들어주세요.');return;}
  jobRequestActive=true;submitting=true;jobStarted=state.pendingRequest.startedAt;jobStage='초안 만들기 요청을 확인하고 있어요';render();startClock();
  try{
    const transfer=state.pendingRequest.kind==='naver';
    const input=generationInput();if(transfer){input.receipts=[];input.notes='';input.facts='';input.location=state.draft.location||null;input.draft=Object.fromEntries(['title','titles','intro','sections','closing','tags','checks','stickers','location'].map(k=>[k,state.draft[k]]));}
    const res=await apiFetch(transfer?'/api/naver':'/api/generate',{method:'POST',headers:{'Content-Type':'application/json','X-Meal-Note':'1'},body:JSON.stringify({...input,requestId:state.pendingRequest.id}),signal:AbortSignal.timeout(60000)});
    const result=await res.json();
    if(!res.ok){if(res.status>=500||res.status===408)throw new Error(result.error);await finishFailure(result.error||'생성을 시작하지 못했어요. 입력은 보관돼 있어요.');return;}
    if(!result.id)throw new Error('접수를 다시 확인하고 있어요.');
    jobId=result.id;state.pendingJob={id:jobId,startedAt:jobStarted,kind:transfer?'naver':'generate'};delete state.pendingRequest;networkRetries=0;submitting=false;await saveNow();render();pollTimer=setTimeout(pollJob,0);
  }catch{jobStage='연결이 잠시 끊겼어요. 입력을 보관하고 접수를 다시 확인하고 있어요';render();pollTimer=setTimeout(submitGeneration,Math.min(30000,3000*++networkRetries));}
  finally{jobRequestActive=false;}
}
async function finishFailure(message){jobId=null;jobAttention=null;submitting=false;delete state.pendingJob;delete state.pendingRequest;clearTimeout(pollTimer);error=message;jobStage='';await saveNow();render();window.scrollTo({top:0,behavior:'smooth'});}
async function pollJob(){
  clearTimeout(pollTimer);if(!jobId||jobRequestActive)return;jobRequestActive=true;const current=jobId;
  try{
    const response=await apiFetch('/api/jobs/'+current,{signal:AbortSignal.timeout(15000)});const job=await response.json();
    if(!response.ok){if(response.status===404||response.status===410){await finishFailure(job.error||'작업이 만료됐어요. 입력 임시저장에서 다시 만들 수 있어요.');return;}throw new Error(job.error);}
    if(jobId!==current)return;
    networkRetries=0;
    if(job.status==='done'){
      if(!job.draft?.sections)throw new Error('초안 결과를 다시 확인하고 있어요.');
      if(state.pendingJob?.kind==='naver'&&state.draft)state.draft.naver=job.draft.naver;else state.draft=job.draft;state.lastUsage=job.usage;delete state.pendingJob;jobId=null;jobAttention=null;view='editor';preview=false;
      const stored=await saveNow();render();window.scrollTo({top:0,behavior:'smooth'});toast(!stored?'초안은 완성됐지만 기기 저장에 실패했어요. 작업 파일로 보관해주세요.':state.draft.naver?.status==='saved'?'네이버 임시저장을 마쳤어요. 수정 화면을 열어보세요.':state.draft.naver?'초안은 보관했어요. 네이버 저장 안내를 확인해주세요.':'초안이 완성되고 이 기기에 저장됐어요.');return;
    }
    if(job.status==='failed'||job.status==='cancelled'){await finishFailure((job.error||'생성을 취소했어요.')+' 사진과 입력은 임시저장되어 있어요.');return;}
    if(JSON.stringify(jobAttention)!==JSON.stringify(job.attention||null)){jobAttention=job.attention||null;render();}jobStage=job.stage||'사진과 이야기를 읽고 있어요';const stage=$('#job-stage');if(stage)stage.textContent=jobStage;
    pollTimer=setTimeout(pollJob,1800);
  }catch{jobStage='연결을 기다리고 있어요. 저장된 입력과 생성 작업을 다시 확인할게요';const stage=$('#job-stage');if(stage)stage.textContent=jobStage;pollTimer=setTimeout(pollJob,Math.min(30000,3000*++networkRetries));}
  finally{jobRequestActive=false;}
}
function plainText(){const d=state.draft;if(!d)return '';return [d.title,MangnaComposition.disclosure(state.sponsorship),d.intro,...d.sections.flatMap(s=>[s.heading,s.body]),d.closing,d.tags.map(t=>'#'+t.replace(/^#/,'')).join(' ')].filter(Boolean).join('\n\n');}
function download(name,data,type){const blob=new Blob([data],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
function filename(){return (state.place||'한편').replace(/[<>:"/\\|?*]/g,'_').slice(0,80);}
function htmlExport(){return `<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(state.draft.title)}</title><style>body{font-family:system-ui;max-width:760px;margin:40px auto;padding:0 24px;line-height:2;color:#344332;text-align:${state.alignment==='left'?'left':'center'}}img,video{max-width:100%;max-height:520px;width:auto;height:auto;object-fit:contain;display:block;margin:24px auto}h1{font-size:28px}</style><h1>${esc(state.draft.title)}</h1>${naverBody(true)}</html>`;}
function showDialog(html){document.querySelector('dialog')?.remove();const dialog=document.createElement('dialog');dialog.innerHTML=html;document.body.append(dialog);dialog.showModal();dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close();});}
function showExport(){if(!state.draft)return;showDialog(`<h2>내 글을 가져가세요.</h2><p>본문은 네이버 블로그에 붙여넣고, 사진은 편집 화면의 순서대로 추가해주세요. 여기서 네이버에 자동 발행하지는 않습니다.</p><div class="toolbar-mini"><button class="button naver-button" data-action="naver">아내 네이버 임시저장</button><button class="button primary" data-action="copy">${icon('copy')}본문 복사</button><button class="button" data-action="download-txt">글 파일 (.txt)</button><button class="button" data-action="download-html">사진과 글 (.html)</button><button class="button" data-action="download-json">편집용 작업 파일 (.json)</button></div><p>작업 파일에는 사진과 수정 내용이 함께 들어 있습니다. ‘내 보관함 → 작업 파일 불러오기’에서 이어 쓸 수 있어요.</p><div class="dialog-actions"><button class="button" data-action="close-dialog">닫기</button></div>`);}
async function loadDraft(id){if(jobId||submitting){toast('현재 초안 생성이 끝난 뒤 다른 글을 열어주세요.');return;}await saveNow();const item=await storeOp('readonly',s=>s.get(id));if(!item)return;state=normalizeState(item);view=state.draft?'editor':'input';preview=false;error='';localStorage.setItem('meal-note-current',id);lastSavedAt=state.modifiedAt;saveStatus='saved';render();window.scrollTo(0,0);if(state.pendingJob){jobId=state.pendingJob.id;jobStarted=state.pendingJob.startedAt;jobStage='진행하던 초안을 다시 확인하고 있어요';view='input';render();startClock();pollJob();}else if(state.pendingRequest)submitGeneration();}
async function importFile(file){try{if(file.size>320*1024*1024)throw new Error('작업 파일이 너무 큽니다.');const data=JSON.parse(await file.text());if(data.format!=='meal-note-v1'||!data.state||!Array.isArray(data.state.photos))throw new Error('망나 모먼트에서 내려받은 작업 파일을 선택해주세요.');const s=data.state;if(s.photos.length>24||!s.photos.every(p=>typeof p.id==='string'&&/^[a-zA-Z0-9_-]{1,80}$/u.test(p.id)&&typeof p.data==='string'&&/^data:image\/(jpeg|png|webp);base64,[A-Za-z0-9+/=]+$/.test(p.data)&&p.data.length<2500000))throw new Error('작업 파일의 사진을 확인해주세요.');for(const k of ['place','area','link','visitDate','menus','notes','facts','sponsorship','style'])if(typeof s[k]!=='string')throw new Error('작업 파일의 입력 정보가 올바르지 않아요.');if(s.draft&&(!Array.isArray(s.draft.sections)||!Array.isArray(s.draft.titles)||!Array.isArray(s.draft.tags)||!Array.isArray(s.draft.checks)||!s.draft.sections.every(x=>typeof x.body==='string'&&Array.isArray(x.photoIds))))throw new Error('작업 파일의 초안 형식이 올바르지 않아요.');if(s.draft){const d=s.draft;if(typeof d.title!=='string'||typeof d.intro!=='string'||typeof d.closing!=='string'||![...d.titles,...d.tags,...d.checks].every(x=>typeof x==='string'))throw new Error('초안 내용을 확인해주세요.');for(const part of d.sections){if(typeof part.heading!=='string'||!part.photoIds.every(id=>s.photos.some(p=>p.id===id)))throw new Error('사진 연결을 확인해주세요.');part.id=crypto.randomUUID();}}await saveNow();state=normalizeState({...s,id:crypto.randomUUID(),pendingJob:undefined});view=state.draft?'editor':'input';await saveNow();render();toast('보관한 사진과 초안을 불러왔어요.');}catch(e){toast(e.message);}}
document.addEventListener('input',e=>{const el=e.target;if(el.dataset.field||el.dataset.photoNote){if(jobId||submitting||photoBusy)return;forkInput();}if(el.dataset.field){state[el.dataset.field]=el.value;if(['place','mapName','mapAddress'].includes(el.dataset.field)){state.locationConfirmed=false;const c=document.getElementById('location-confirmed');if(c)c.checked=false;}scheduleSave();if(['visitDate','visitTime'].includes(el.dataset.field))updateVisitPreview();}if(el.dataset.photoNote){const photo=state.photos.find(p=>p.id===el.dataset.photoNote);if(photo)photo.note=el.value;scheduleSave();}if(el.dataset.draftField&&state.draft){state.draft[el.dataset.draftField]=el.dataset.draftField==='tags'?el.value.split(/[\s,]+/).map(t=>t.replace(/^#/, '')).filter(Boolean):el.value;scheduleSave();}if(el.dataset.section&&state.draft){const s=state.draft.sections.find(s=>s.id===el.dataset.section);if(s)s[el.dataset.prop]=el.value;scheduleSave();}if(el.classList.contains('auto-grow'))grow(el);const count=$('#char-count');if(count&&state.draft)count.textContent=plainText().length.toLocaleString()+'자';});
document.addEventListener('change',e=>{if(e.target.id==='photo-picker')addPhotos(e.target.files);if(e.target.id==='import-picker'&&e.target.files[0]){if(jobId||submitting||photoBusy)return toast('현재 작업을 마친 뒤 불러와주세요.');importFile(e.target.files[0]);}});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action;try{
if((jobId||submitting||photoBusy)&&['new','load','import','photo-remove','photo-up','style'].includes(a))return toast('현재 작업을 마친 뒤 변경해주세요.');
if(a==='upload')$('#photo-picker').click();
if(a==='pair')await pairDevice();
if(a==='status'){toast('Codex 구독 연결을 확인하고 있어요.');await checkStatus();}
if(a==='style'){if(jobId||submitting)return;forkInput();state.style=b.dataset.style;scheduleSave();render();}
if(a==='new'){if(jobId)return toast('현재 생성이 끝난 뒤 새 글을 시작해주세요.');await saveNow();state=fresh();lastSavedAt=0;saveStatus='empty';view='input';error='';localStorage.removeItem('meal-note-current');render();window.scrollTo(0,0);}
if(a==='workspace'||a==='input'){view='input';render();window.scrollTo(0,0);}
if(a==='library'){await saveNow();view='library';render();window.scrollTo(0,0);}
if(a==='editor'&&state.draft){view='editor';render();window.scrollTo(0,0);}
if(a==='load')await loadDraft(b.dataset.id);
if(a==='photo-remove'){if(jobId||submitting)return;forkInput();state.photos=state.photos.filter(p=>p.id!==b.dataset.id);scheduleSave();render();}
if(a==='photo-up'){if(jobId||submitting)return;forkInput();const i=state.photos.findIndex(p=>p.id===b.dataset.id);if(i>0)[state.photos[i-1],state.photos[i]]=[state.photos[i],state.photos[i-1]];scheduleSave();render();}
if(a==='save-input'){if(!hasContent())return toast('사진이나 메모를 먼저 넣어주세요.');if(await saveNow()){navigator.storage?.persist?.().catch(()=>{});toast('사진과 입력을 임시저장했어요. 내 보관함에서 이어 쓸 수 있어요.');}}
if(a==='retry-job'){if(jobId)await pollJob();else if(state.pendingRequest)await submitGeneration();}
if(a==='generate')await startGeneration();
if(a==='cancel'&&jobId){await apiFetch('/api/jobs/'+jobId+'/cancel',{method:'POST',headers:{'Content-Type':'application/json','X-Meal-Note':'1'},body:'{}'});toast('생성 취소를 요청했어요.');}
if(a==='preview'){preview=!preview;render();}
if(a==='copy'){await navigator.clipboard.writeText(plainText());toast('본문을 복사했어요. 사진은 네이버 편집기에서 따로 추가해주세요.');}
if(a==='export')showExport();
if(a==='download-txt')download(filename()+'.txt',plainText(),'text/plain;charset=utf-8');
if(a==='download-html')download(filename()+'.html',htmlExport(),'text/html;charset=utf-8');
if(a==='download-json'){await saveNow();download(filename()+'.json',JSON.stringify({format:'meal-note-v1',state},null,2),'application/json');}
if(a==='title'){state.draft.title=state.draft.titles[Number(b.dataset.index)];scheduleSave();render();}
if(a==='section-up'||a==='section-down'){const arr=state.draft.sections,i=arr.findIndex(s=>s.id===b.dataset.id),j=i+(a==='section-up'?-1:1);if(j>=0&&j<arr.length)[arr[i],arr[j]]=[arr[j],arr[i]];scheduleSave();render();}
if(a==='add-section'){state.draft.sections.push({id:crypto.randomUUID(),heading:'내가 남기고 싶은 이야기',body:'',photoIds:[]});scheduleSave();render();const fields=document.querySelectorAll('[data-prop=body]');fields[fields.length-1]?.focus();}
if(a==='import')$('#import-picker').click();
if(a==='close-dialog')document.querySelector('dialog')?.close();
if(a==='help')showDialog(`<h2>사진에서 한 편까지</h2><ol><li>식당 이름과 지점을 적고 사진을 골라주세요.</li><li>메뉴 이름이나 맛에 대한 한두 줄을 더해주세요. 없어도 시작할 수 있어요.</li><li>초안 만들기를 누르면 연결된 PC의 Codex가 사진을 읽고 글을 만듭니다.</li><li>제목과 문단을 직접 고친 뒤 본문을 복사하거나 파일로 보관하세요.</li></ol><p>별도 API 키나 API 결제는 사용하지 않습니다. 기존 Codex 구독 한도를 사용하며, 한도가 부족하면 멈춥니다. 초안 생성 PC가 켜져 있어야 생성할 수 있어요. 새 기기는 생성 PC의 http://127.0.0.1:4190 에서 한 번 승인해주세요.</p><p>사진은 최대 1600px로 줄여 저장합니다. 브라우저 데이터를 삭제하면 저장된 초안도 지워지므로 중요한 글은 편집용 작업 파일로 내려받아주세요.</p><div class="dialog-actions"><button class="button primary" data-action="close-dialog">시작해볼게요</button></div>`);
}catch(err){toast(err.message||'작업을 마치지 못했어요. 다시 시도해주세요.');}});
window.addEventListener('beforeunload',e=>{if(photoBusy){e.preventDefault();e.returnValue='';}if(hasContent())saveNow();});
document.addEventListener('visibilitychange',()=>{if(document.hidden)saveNow();});
async function boot(){
  try{db=await openDB();storageReady=true;library=await storeOp('readonly',s=>s.getAll());library.sort((a,b)=>b.modifiedAt-a.modifiedAt);let current;try{current=localStorage.getItem('meal-note-current');}catch{}
    state=normalizeState(library.find(d=>d.id===current)||fresh());view=state.draft?'editor':'input';if(hasContent()){lastSavedAt=state.modifiedAt;saveStatus='saved';}
    if(state.pendingJob){jobId=state.pendingJob.id;jobStarted=state.pendingJob.startedAt;jobStage='진행하던 초안을 다시 확인하고 있어요';view='input';}
  }catch{error='브라우저 저장 공간을 사용할 수 없어요. 작업 파일로 보관해주세요.';saveStatus='error';}
  render();checkStatus();recoveryEvents();if(jobId){startClock();pollJob();}else if(state.pendingRequest)submitGeneration();
}
boot();

